                      Material(
                        color: Colors.transparent,
                        child: InkWell(
                          onTap: area.onTap,
                          customBorder: isCircle
                              ? const CircleBorder()
                              : RoundedRectangleBorder(
                                  borderRadius: BorderRadius.circular(10),
                                ),
                          splashColor: Colors.white.withValues(alpha: 0.3),
                          highlightColor: Colors.white.withValues(alpha: 0.1),
                          child: Container(),
                        ),
                      ),
                      if (debugLayout)
                        IgnorePointer(
                          child: Container(
                            decoration: BoxDecoration(
                              color: Colors.blue.withValues(alpha: 0.3),
                              border: Border.all(color: Colors.blue, width: 2),
                              shape: isCircle
                                  ? BoxShape.circle
                                  : BoxShape.rectangle,
                              borderRadius: isCircle
                                  ? null
                                  : BorderRadius.circular(10),
                            ),
                            child: Center(
                              child: Text(
                                area.debugLabel,
                                style: _debugLabelStyle(8),
                                textAlign: TextAlign.center,
                              ),
                            ),
                          ),
                        ),
                    ],
                  ),
                );
              }),

            if (debugLayout)
              Positioned.fromRect(
                rect: absoluteLcdRect,
                child: Container(
                  decoration: BoxDecoration(
                    color: Colors.red.withValues(alpha: 0.3),
                    border: Border.all(color: Colors.red, width: 2),
                  ),
                  child: Center(
                    child: Text(
                      'LCD Area\n${(lcdRect.left * 100).toStringAsFixed(1)}%, ${(lcdRect.top * 100).toStringAsFixed(1)}%\n${(lcdRect.width * 100).toStringAsFixed(1)}% x ${(lcdRect.height * 100).toStringAsFixed(1)}%',
                      style: _debugLabelStyle(10),
                      textAlign: TextAlign.center,
                    ),
                  ),
                ),
              ),

            // Media controls (optional overlay pinned near screen bottom).
            if (mediaControls != null)
              Positioned(
                left: 0,
                right: 0,
                bottom: 40,
                child: mediaControls!,
              ),
          ],
        );
      },
    );
  }
}

